local StainedGlassMaker = {}
local PRODUCTS = {
    simple_leaded = { name = "Preprosta svinčevana", glassCost = 1, leadCost = 1, time = 2, cost = 30, lightTransmission = 5, prestige = 1, description = "Preprosto svinčevano steklo za samostane." },
    geometric_panel = { name = "Geometrijski panel", glassCost = 2, leadCost = 1, time = 3, cost = 75, lightTransmission = 7, prestige = 3, description = "Geometrijski vzorec iz barvnega stekla." },
    floral_window = { name = "Floralno okno", glassCost = 2, leadCost = 1, paintCost = 1, time = 5, cost = 180, lightTransmission = 9, prestige = 6, happiness = 1, description = "Floralni motiv s svetlobo." },
    heraldic_window = { name = "Heraldično okno", glassCost = 3, leadCost = 1, paintCost = 1, time = 7, cost = 400, lightTransmission = 11, prestige = 12, happiness = 2, description = "Heraldični grb v barvnem steklu." },
    gold_flecked_window = { name = "Zlatorobno okno", glassCost = 3, goldCost = 1, leadCost = 1, paintCost = 1, time = 9, cost = 850, lightTransmission = 13, prestige = 20, happiness = 4, description = "Okno z zlatimi drozgi v steklu." },
    royal_chapel_rose_window = { name = "Kraljevski rozetno okno", glassCost = 5, goldCost = 2, silverCost = 1, leadCost = 2, paintCost = 2, jewelCost = 1, time = 14, cost = 2200, lightTransmission = 20, prestige = 55, happiness = 10, description = "Veliki rozetni okno kraljevske kapele z dragulji in zlatom." },
}
local BUILDINGS = {
    workshop = { name = "Steklarska delavnica", cost = { gold = 320, wood = 140 }, upkeep = 8, qualityBonus = 5 },
    kiln_room = { name = "Pečnica", cost = { gold = 950, wood = 250, stone = 250, glass = 8 }, upkeep = 22, qualityBonus = 18 },
    painting_room = { name = "Slikalnica", cost = { gold = 1900, wood = 300, stone = 400, silver = 25, paint = 8 }, upkeep = 45, qualityBonus = 30 },
    royal_glass_atelier = { name = "Kraljevski atelje stekla", cost = { gold = 7000, wood = 600, stone = 800, gold = 50, glass = 20 }, upkeep = 130, qualityBonus = 55, prestigeBonus = 33 },
}
StainedGlassMaker.glassStock = 18; StainedGlassMaker.leadStock = 14; StainedGlassMaker.paintStock = 10; StainedGlassMaker.goldStock = 6; StainedGlassMaker.silverStock = 6; StainedGlassMaker.jewelStock = 4
StainedGlassMaker.productStock = {}; StainedGlassMaker.buildings = {}; StainedGlassMaker.maker = nil; StainedGlassMaker.activeMaking = {}; StainedGlassMaker.totalProducts = 0; StainedGlassMaker.dayTimer = 0
function StainedGlassMaker.init() StainedGlassMaker.glassStock=18; StainedGlassMaker.leadStock=14; StainedGlassMaker.paintStock=10; StainedGlassMaker.goldStock=6; StainedGlassMaker.silverStock=6; StainedGlassMaker.jewelStock=4; StainedGlassMaker.productStock={}; StainedGlassMaker.buildings={}; StainedGlassMaker.maker=nil; StainedGlassMaker.activeMaking={}; StainedGlassMaker.totalProducts=0; StainedGlassMaker.dayTimer=0; print("[StainedGlassMaker] Royal Stained Glass Maker System initialized (6 products, 4 buildings)") end
function StainedGlassMaker.hireMaker(n,s) s=s or math.random(50,90); local c=490+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; StainedGlassMaker.maker={name=n or ("Steklar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Steklar najet: %s (spretnost: %d)",StainedGlassMaker.maker.name,s),"success") end; return true end
function StainedGlassMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function StainedGlassMaker.build(id) local ok,e=StainedGlassMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(StainedGlassMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function StainedGlassMaker.getQualityBonus() local b=0; for _,bd in ipairs(StainedGlassMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function StainedGlassMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.glassCost and StainedGlassMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.leadCost and StainedGlassMaker.leadStock<(d.leadCost or 0) then return false,"Premalo svinca" end; if d.paintCost and StainedGlassMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.goldCost and StainedGlassMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.silverCost and StainedGlassMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.jewelCost and StainedGlassMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #StainedGlassMaker.buildings==0 then return false,"Potrebna delavnica" end; if not StainedGlassMaker.maker then return false,"Potreben steklar" end; return true end
function StainedGlassMaker.make(pt,qty) qty=qty or 1; local ok,e=StainedGlassMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.glassCost then StainedGlassMaker.glassStock=StainedGlassMaker.glassStock-d.glassCost*qty end; if d.leadCost then StainedGlassMaker.leadStock=StainedGlassMaker.leadStock-d.leadCost*qty end; if d.paintCost then StainedGlassMaker.paintStock=StainedGlassMaker.paintStock-d.paintCost*qty end; if d.goldCost then StainedGlassMaker.goldStock=StainedGlassMaker.goldStock-d.goldCost*qty end; if d.silverCost then StainedGlassMaker.silverStock=StainedGlassMaker.silverStock-d.silverCost*qty end; if d.jewelCost then StainedGlassMaker.jewelStock=StainedGlassMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if StainedGlassMaker.maker then t=math.max(1,t-math.floor(StainedGlassMaker.maker.skill/12)) end; table.insert(StainedGlassMaker.activeMaking,{id="stained_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,lightTransmission=d.lightTransmission or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function StainedGlassMaker.completeMaking(m) local q=1.0+(StainedGlassMaker.getQualityBonus()/100); if StainedGlassMaker.maker then q=q+(StainedGlassMaker.maker.skill/180) end; q=math.min(2.0,q); StainedGlassMaker.productStock[m.productType]=(StainedGlassMaker.productStock[m.productType] or 0)+m.quantity; StainedGlassMaker.totalProducts=StainedGlassMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if StainedGlassMaker.maker then StainedGlassMaker.maker.itemsMade=StainedGlassMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then StainedGlassMaker.maker.skill=math.min(100,StainedGlassMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Steklo izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"stainedglass.completed",{productName=m.productName,prestige=m.prestige}) end end
function StainedGlassMaker.update(dt) if not _G.state then return end; StainedGlassMaker.dayTimer=StainedGlassMaker.dayTimer+dt; if StainedGlassMaker.dayTimer>=30 then StainedGlassMaker.dayTimer=0; for i=#StainedGlassMaker.activeMaking,1,-1 do local m=StainedGlassMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then StainedGlassMaker.completeMaking(m); table.remove(StainedGlassMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(StainedGlassMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if StainedGlassMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function StainedGlassMaker.getStats() return {glassStock=StainedGlassMaker.glassStock,leadStock=StainedGlassMaker.leadStock,paintStock=StainedGlassMaker.paintStock,goldStock=StainedGlassMaker.goldStock,silverStock=StainedGlassMaker.silverStock,jewelStock=StainedGlassMaker.jewelStock,productStock=StainedGlassMaker.productStock,numBuildings=#StainedGlassMaker.buildings,hasMaker=StainedGlassMaker.maker~=nil,makerName=StainedGlassMaker.maker and StainedGlassMaker.maker.name or "—",makerSkill=StainedGlassMaker.maker and StainedGlassMaker.maker.skill or 0,activeMaking=#StainedGlassMaker.activeMaking,totalProducts=StainedGlassMaker.totalProducts} end
return StainedGlassMaker
